    target_obj = m.group(1).strip().lower()
    target_rec = m.group(2).strip().lower()
    target_rec = re.sub(r"\s+\d+$", "", target_rec).strip()

    def parse_objects(text, objname):
        out = []
        for mm in re.finditer(r"\b" + re.escape(objname) + r"\s+(\d+)", text):
            out.append(int(mm.group(1)))
        return out

    def parse_recepts(text):
        out = []
        for mm in re.finditer(r"([a-z]+(?:\s[a-z]+)*)\s+(\d+)", text):
            name = mm.group(1).strip().lower()
            num = int(mm.group(2))
            out.append((name, num))
        return out

    room = env.observation
    recs = parse_recepts(room)
    seen = set()
    uniq = []
