            visited.add(rec)
            queue.append(rec)

    found = {}
    target_rec_str = None

    while queue:
        rec = queue.popleft()
        r = env.step(f"go to {rec}")
        if "closed" in r.lower() and "open" not in r.lower():
            env.step(f"open {rec}")
        text = env.observation
        parts = rec.rsplit(" ", 1)
