        return [int(mm.group(1)) for mm in re.finditer(r"\b" + re.escape(objname) + r"\s+(\d+)", text)]

    # Extract receptacles from a text like the room description or an observation.
    # Room description: "you see a armchair 1, a coffeetable 1, ..."
    # Observation after go to: "On the coffeetable 1, you see a creditcard 3, ..."
    # We only want receptacle names, not object names. Receptacles are the ones
    # in the room description. Objects appear after "you see".
    def parse_room_recepts(text):
        # Take the part before "you see" to avoid object names.
        head = re.split(r"you see", text, maxsplit=1)[0]
        out = []
        for mm in re.finditer(r"\b([a-z]+(?:\s[a-z]+)*)\s+(\d+)", head):
            name = mm.group(1).strip().lower()
            num = int(mm.group(2))
            if name and name not in ("a", "an", "the"):
                out.append((name, num))
        return out

    room = env.observation
    recs = parse_room_recepts(room)

    queue = deque()
    visited = set()
    for n, k in recs:
        rec = f"{n} {k}"
        if rec not in visited:
            visited.add(rec)
            queue.append(rec)

    found = {}
    target_rec_str = None

