        # Look only in the "you see" part after "On the X, you see ..." which lists objects,
        # but newly revealed receptacles might also be listed. We'll take any name+number
        # that isn't the target object type, but safer: only add if it doesn't look like an object.
        # We'll add them and try; invalid ones just do nothing.
        for mm in re.finditer(r"\b([a-z]+(?:\s[a-z]+)*)\s+(\d+)", text):
            name = mm.group(1).strip().lower()
            num = int(mm.group(2))
            if name in ("a", "an", "the"):
                continue
